import { resolveAssetUrl } from '../../config/loadConfig';
import type { BasemapConfig } from '../../config/schema';
import { enuFromLngLat, latToMercator, lngToMercator, tileBounds, type GeoBounds, type LngLat } from '../../shared/geo';

/**
 * 三维院区的影像地面：以锚点为中心取 (2·radius+1)² 张瓦片。
 *
 * **为什么不复用 `useMapTiles`**：那个 hook 是「屏幕空间」的——按舞台尺寸、当前缩放倍数、DPR 选层级，
 * 再算可见范围、按中心优先排队、稳定 140ms 才换层。三维地面要的正好相反：固定层级、按锚点对称、
 * 一次算清。硬套会把那套换层状态机带进渲染循环。
 *
 * **但取图口径必须一致**：同一套 `{z}/{x}/{y}/{s}` 替换、同一套子域分配、同一套主源/备用源，
 * 这样同一张瓦片在两处是同一个 URL，浏览器缓存与 CDN 都命中同一份。
 * 两种子域写法都支持（见 `tileUrl`）：模板写 `{s}`，或模板写死 `t0` 并只给出候选数字。
 *
 * 验算（`groundTiles.test.ts`）：z=18 在纬度 30.51° 处每张瓦片 ≈ 131.7 米，3×3 ≈ 395 米。
 */

/** 赤道周长（米），用于把「每度米数」换回「每张瓦片多少米」。 */
const EARTH_CIRCUMFERENCE_M = 40_075_016.686;

export interface GroundTile {
  /** `z/x/y`；注记层多一个 `/overlay` 后缀，保证同一格的两层不重键。 */
  key: string;
  z: number;
  x: number;
  y: number;
  url: string;
  fallbackUrl?: string;
  /** 注记层（如天地图 cva_w）：与底图同 z/x/y，半透明叠在上面。 */
  overlay: boolean;
  bounds: GeoBounds;
}

export interface GroundTilePlacement {
  /** 瓦片中心相对锚点的东向偏移（米）。 */
  east: number;
  /** 瓦片中心相对锚点的北向偏移（米）。 */
  north: number;
  /** 瓦片边长（米）。Web Mercator 的瓦片在该纬度的小范围里是正方形的，误差 < 0.01%。 */
  size: number;
}

/** 一张瓦片在该纬度覆盖多少米。 */
export function tileMeters(zoom: number, lat: number): number {
  return (EARTH_CIRCUMFERENCE_M * Math.cos((lat * Math.PI) / 180)) / 2 ** zoom;
}

/** 解析好的模板与子域：固定铺地（`tilesAroundAnchor`）与流式铺地（`groundStream`）共用一份。 */
export interface GroundTileUrls {
  primary: string;
  overlay?: string;
  fallback?: string;
  fallbackOverlay?: string;
  subdomains: readonly string[];
}

export function prepareGroundUrls(basemap: BasemapConfig): GroundTileUrls | null {
  if (basemap.kind !== 'tiles') return null;
  return {
    primary: resolveAssetUrl(basemap.urlTemplate),
    overlay: basemap.overlayTemplate ? resolveAssetUrl(basemap.overlayTemplate) : undefined,
    fallback: basemap.fallbackTemplate ? resolveAssetUrl(basemap.fallbackTemplate) : undefined,
    fallbackOverlay: basemap.fallbackOverlayTemplate ? resolveAssetUrl(basemap.fallbackOverlayTemplate) : undefined,
    subdomains: basemap.subdomains ?? [],
  };
}

/** 按地图引擎同一套规则填模板（见 `features/map/mapNavigation.ts` 的 `tilesForViewport`）。 */
export function tileUrl(template: string, zoom: number, x: number, y: number, subdomains: readonly string[]): string {
  const subdomain = subdomains.length > 0 ? subdomains[(x + y) % subdomains.length] ?? '' : '';
  const filled = template
    .replace('{z}', String(zoom))
    .replace('{x}', String(x))
    .replace('{y}', String(y))
    .replace('{s}', subdomain);
  if (template.includes('{s}') || !subdomain) return filled;
  return filled.replace(/\/\/t\d+\./, `//t${subdomain}.`);
}

/**
 * 造一张瓦片记录。`rawX` 是**未折回**的列号，只用来做 key：跨 180° 时折回后的 `x` 会撞键。
 */
export function makeGroundTile(
  urls: GroundTileUrls,
  zoom: number,
  x: number,
  y: number,
  rawX: number,
  overlay: boolean,
): GroundTile {
  const count = 2 ** zoom;
  const wrappedX = ((x % count) + count) % count;
  const bounds = tileBounds(zoom, wrappedX, wrappedX, y, y);
  const template = (overlay ? urls.overlay : urls.primary) ?? urls.primary;
  const fallbackTemplate = overlay ? urls.fallbackOverlay : urls.fallback;
  return {
    key: `${zoom}/${rawX}/${y}${overlay ? '/overlay' : ''}`,
    z: zoom,
    x: wrappedX,
    y,
    bounds,
    overlay,
    url: tileUrl(template, zoom, wrappedX, y, urls.subdomains),
    fallbackUrl: fallbackTemplate ? tileUrl(fallbackTemplate, zoom, wrappedX, y, []) : undefined,
  };
}

/**
 * 以 `anchor` 为中心取瓦片。返回顺序即挂载顺序：**先底图、后注记，各自中心优先**。
 * `y` 越界的瓦片直接丢掉（南北极方向没有瓦片）；`x` 按 Web Mercator 环绕折回。
 */
export function tilesAroundAnchor(anchor: LngLat, zoom: number, radius: number, basemap: BasemapConfig): GroundTile[] {
  const urls = prepareGroundUrls(basemap);
  if (!urls) return [];
  const count = 2 ** zoom;
  const centerX = Math.floor(lngToMercator(anchor.lng) * count);
  const centerY = Math.floor(latToMercator(anchor.lat) * count);

  const offsets: Array<{ dx: number; dy: number }> = [];
  for (let dx = -radius; dx <= radius; dx += 1) {
    for (let dy = -radius; dy <= radius; dy += 1) offsets.push({ dx, dy });
  }
  // 中心优先：先出脚底下那张，视觉上像「地面从脚下长出来」。
  offsets.sort((a, b) => a.dx ** 2 + a.dy ** 2 - (b.dx ** 2 + b.dy ** 2));

  const base: GroundTile[] = [];
  const notes: GroundTile[] = [];
  for (const { dx, dy } of offsets) {
    const x = centerX + dx;
    const y = centerY + dy;
    if (y < 0 || y >= count) continue;
    base.push(makeGroundTile(urls, zoom, x, y, x, false));
    if (urls.overlay) notes.push(makeGroundTile(urls, zoom, x, y, x, true));
  }
  return [...base, ...notes];
}

/** 把一张瓦片换算成场景坐标（`+X 东 / -Z 北`，原点 = 锚点）。 */
export function placeGroundTile(tile: GroundTile, anchor: LngLat): GroundTilePlacement {
  const centerLng = (tile.bounds.west + tile.bounds.east) / 2;
  const centerLat = (tile.bounds.south + tile.bounds.north) / 2;
  const { east, north } = enuFromLngLat(anchor, { lng: centerLng, lat: centerLat });
  return { east, north, size: tileMeters(tile.z, centerLat) };
}
