import * as THREE from 'three';
import type { BasemapConfig } from '../../config/schema';
import type { LngLat } from '../../shared/geo';
import { placeGroundTile, tileMeters, tilesAroundAnchor } from './groundTiles';

/**
 * 三维院区的影像地面（`docs/project/ROAM-PLAN-A.md` §2 S2）。
 *
 * 做法：按锚点取 (2·radius+1)² 张瓦片，每张一个**平铺的矩形**，位置由经纬度换算成场景米制
 * （见 `groundTiles.placeGroundTile`），覆盖在模型原点下方若干厘米——模型自带的地面是实体面，
 * 影像必须让在它下面，否则两面共面会闪（z-fighting）。
 *
 * 三个「不做」：不做球面/地形（院区 400 米内地球曲率 < 1.5 cm）、不做雾外裁剪、
 * 不做加载动画（地面是背景，铺上就行；失败的那张直接隐藏）。
 */

/**
 * 影像地面相对模型原点下沉多少米。
 * 0.35 m 是「既不闪面、又不会被看成悬空」的折中：相机最远 900 m，这点高差在远景里看不出来，
 * 近景又足够避开模型自带地面与平台的深度冲突。
 */
export const GROUND_DROP_M = 0.35;

export interface GroundLayerOptions {
  anchor: LngLat;
  zoom: number;
  radius: number;
  overlayOpacity: number;
  basemap: BasemapConfig;
  /** 地面所在高度（场景米），一般是 `placement.elevationM - GROUND_DROP_M`。 */
  elevation: number;
  /** 每张瓦片「贴上」或「失败」后回调一次——场地场景是按需渲染的，必须由它置脏。 */
  onUpdate?(): void;
}

export interface GroundLayer {
  group: THREE.Group;
  /** 已贴上的张数 / 总张数（含注记层），供探针与 `?perf=1` 读取。 */
  readonly stats: { loaded: number; total: number; failed: number };
  /** 注记层透明度（标定面板的滑杆）。只影响注记，底图影像保持不透明才有对齐价值。 */
  setOpacity(value: number): void;
  /** 整层升降（标定面板的「高度」滑杆）。 */
  setElevation(value: number): void;
  dispose(): void;
}

export function createGroundLayer(options: GroundLayerOptions): GroundLayer {
  const group = new THREE.Group();
  group.name = 'site-ground';
  const tiles = tilesAroundAnchor(options.anchor, options.zoom, options.radius, options.basemap);
  const stats = { loaded: 0, total: tiles.length, failed: 0 };
  // 探针与 `?perf=1` 要能直接从场景树上读到进度，不用另开全局变量。
  group.userData.groundStats = stats;
  const materials: THREE.MeshBasicMaterial[] = [];
  /** 注记层材质（`overlayOpacity` 的落点）与全部瓦片网格（`setElevation` 的落点）。 */
  const overlayMaterials: THREE.MeshBasicMaterial[] = [];
  const meshes: THREE.Mesh[] = [];
  const loader = new THREE.TextureLoader();
  loader.setCrossOrigin('anonymous');
  let disposed = false;

  // 同一层级的瓦片尺寸只差在小数点后第四位（每张的中心纬度不同），共用一个几何体即可：
  // 390 米的铺地范围内累计误差 < 1 厘米，看不出来，却省掉 17 份顶点缓冲。
  const size = tileMeters(options.zoom, options.anchor.lat);
  const geometry = new THREE.PlaneGeometry(size, size);
  geometry.rotateX(-Math.PI / 2);

  for (const tile of tiles) {
    const placement = placeGroundTile(tile, options.anchor);
    const material = new THREE.MeshBasicMaterial({
      // 底图不透明、注记层透明且不写深度（半透明叠加不该挡住后面的地面）。
      transparent: tile.overlay,
      opacity: tile.overlay ? options.overlayOpacity : 1,
      depthWrite: !tile.overlay,
      polygonOffset: true,
      polygonOffsetFactor: 1,
      polygonOffsetUnits: 1,
    });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(placement.east, options.elevation, -placement.north);
    mesh.renderOrder = tile.overlay ? 1 : 0;
    mesh.userData.groundTile = tile.key;
    materials.push(material);
    if (tile.overlay) overlayMaterials.push(material);
    meshes.push(mesh);
    group.add(mesh);

    const load = (url: string, fallbackUrl?: string) => {
      loader.load(
        url,
        texture => {
          if (disposed) {
            texture.dispose();
            return;
          }
          texture.colorSpace = THREE.SRGBColorSpace;
          material.map = texture;
          material.needsUpdate = true;
          stats.loaded += 1;
          options.onUpdate?.();
        },
        undefined,
        () => {
          if (disposed) return;
          // 主源这张挂了 → 同 z/x/y 换备用源再试一次（与地图引擎同一套规则）。
          if (fallbackUrl) {
            load(fallbackUrl);
            return;
          }
          stats.failed += 1;
          mesh.visible = false;
          options.onUpdate?.();
        },
      );
    };
    load(tile.url, tile.fallbackUrl);
  }

  return {
    group,
    stats,
    setOpacity(value) {
      const next = Math.min(1, Math.max(0, value));
      for (const material of overlayMaterials) {
        material.opacity = next;
        material.needsUpdate = true;
      }
    },
    setElevation(value) {
      for (const mesh of meshes) mesh.position.y = value;
    },
    dispose() {
      disposed = true;
      for (const material of materials) {
        material.map?.dispose();
        material.dispose();
      }
      geometry.dispose();
      group.removeFromParent();
      group.clear();
    },
  };
}
