/**
 * 三维院区的标定面板（`docs/project/ROAM-PLAN-A.md` §2 S3）。
 *
 * 只在 `?calibrate=1` 时挂载（见 `SiteScene`）。三个滑杆 + 影像透明度即时作用到场景，
 * 「模型线框」用来把建筑轮廓和影像对齐看；满意后「应用」写本地覆盖层、
 * 「复制 JSON」拿走片段、dev 下还能直接写回 `config/museum.json`。
 */
import type { PlacementDraft } from './usePlacementDraft';
import './site-calibration.css';

export interface SiteCalibrationPanelProps {
  draft: PlacementDraft;
  wireframe: boolean;
  onWireframeChange(value: boolean): void;
  /** dev server 下 `probeConfigWriter()` 可用，才有「写回 museum.json」。 */
  canWriteBack: boolean;
  writeBackState: 'idle' | 'busy' | 'done' | 'error';
  onWriteBack(): void;
}

const SLIDERS = [
  { key: 'headingDeg', label: '航向', unit: '°', min: -180, max: 180, step: 0.5, digits: 1 },
  { key: 'elevationM', label: '高度', unit: 'm', min: -5, max: 5, step: 0.05, digits: 2 },
  { key: 'scale', label: '缩放', unit: '×', min: 0.9, max: 1.1, step: 0.001, digits: 4 },
] as const;

export function SiteCalibrationPanel({
  draft,
  wireframe,
  onWireframeChange,
  canWriteBack,
  writeBackState,
  onWriteBack,
}: SiteCalibrationPanelProps) {
  const { placement, ground } = draft;
  return (
    <aside className="site-calibration" aria-label="三维院区标定">
      <header>
        <strong>配准标定</strong>
        <span className="site-calibration-anchor">
          锚点 {placement.anchor.lng.toFixed(6)}, {placement.anchor.lat.toFixed(6)}
        </span>
      </header>

      {SLIDERS.map(slider => (
        <label key={slider.key} className="site-calibration-row">
          <span className="site-calibration-name">
            {slider.label}
            <em>
              {placement[slider.key].toFixed(slider.digits)}
              {slider.unit}
            </em>
          </span>
          <input
            type="range"
            min={slider.min}
            max={slider.max}
            step={slider.step}
            value={placement[slider.key]}
            aria-label={slider.label}
            onChange={event => draft.set({ [slider.key]: Number(event.target.value) })}
          />
        </label>
      ))}

      <label className="site-calibration-row">
        <span className="site-calibration-name">
          注记透明度
          <em>{Math.round(ground.overlayOpacity * 100)}%</em>
        </span>
        <input
          type="range"
          min={0}
          max={1}
          step={0.02}
          value={ground.overlayOpacity}
          aria-label="注记透明度"
          onChange={event => draft.setOpacity(Number(event.target.value))}
        />
      </label>

      <label className="site-calibration-toggle">
        <input type="checkbox" checked={wireframe} onChange={event => onWireframeChange(event.target.checked)} />
        模型线框
      </label>

      <div className="site-calibration-actions">
        <button type="button" onClick={draft.save} disabled={draft.saved}>
          {draft.saved ? '已应用' : '应用（存本机）'}
        </button>
        <button type="button" onClick={draft.reset}>
          复位
        </button>
        <button type="button" onClick={() => { void navigator.clipboard?.writeText(draft.json); }}>
          复制 JSON
        </button>
        {canWriteBack && (
          <button type="button" onClick={onWriteBack} disabled={writeBackState === 'busy'}>
            {writeBackState === 'done' ? '已写回' : writeBackState === 'busy' ? '写入中…' : '写回 museum.json'}
          </button>
        )}
      </div>

      {writeBackState === 'error' && <p className="site-calibration-note">写回失败，用「复制 JSON」手动粘。</p>}
      <details className="site-calibration-json">
        <summary>配置片段</summary>
        <pre>{draft.json}</pre>
      </details>
    </aside>
  );
}
