import { memo, useCallback, useEffect, useMemo, useRef, useState, type ComponentType } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';
import { probeConfigWriter, writeConfigDefaults } from '../../config/configWriter';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { BasemapConfig, PlacementConfig, SiteModelConfig } from '../../config/schema';
import { clearAssetCaches } from '../../shared/assetCache';
import { activeScenePalette } from '../../shared/scenePalette';
import { dampingForFrame } from '../../shared/orbitDamping';
import { coarseRotateSpeedScale, detectCoarsePointer } from '../../shared/orbitSpeed';
import { enuFromScene } from '../../shared/geo';
import { disposeModelRoot } from '../devices/deviceModel';
import { PointerTap } from '../devices/pointer-tap';
import { createGroundLayer, GROUND_DROP_M } from './GroundLayer';
import { createGroundStreamer, type GroundStreamer } from './GroundStreamer';
import type { GroundWindow } from './groundStream';
import { SiteCalibrationPanel } from './SiteCalibrationPanel';
import { placementTransform } from './placement';
import { findHotspotId, loadSiteModel, resolveSiteHotspots, type LoadedSiteModel } from './siteModel';
import { usePlacementDraft } from './usePlacementDraft';

/**
 * OrbitControls 的基准阻尼系数（60fps 下每帧衰减）。运行时按真实帧长换算成等价的每帧系数，
 * 否则低帧率手机上惯性会被按帧摊成好几秒（见 shared/orbitDamping.ts）。
 */
const SITE_DAMPING_BASE = 0.09;

/**
 * 旋转灵敏度基准（桌面 1440×900 下手感正常的那个值）。手指设备上运行时按画布高度补偿：
 * OrbitControls 的每像素弧度是 `rotateSpeed * 2π / 画布高`，平板竖屏的画布比桌面高约 1/3，
 * 于是同样的手指位移转过的角度少四分之一（见 shared/orbitSpeed.ts）。
 */
const SITE_ROTATE_SPEED = 0.55;

/** 场地模型（33 MB 整包）下载失败后的自动重试次数。 */
const SITE_LOAD_RETRIES = 2;

export interface SiteMarkerConfig {
  id: string;
  label: string;
  description: string;
}
export interface SiteViewState {
  /** 每次自增即复位视角。 */
  reset: number;
  rotate: boolean;
  top: boolean;
}

export interface SiteSceneProps {
  site: SiteModelConfig;
  markers: SiteMarkerConfig[];
  view: SiteViewState;
  onActivate(hotspotId: string): void;
  onProgress?(percent: number): void;
  onError?(message: string): void;
  onIssues?(count: number): void;
  onReady?(): void;
  retryToken?: number;
  /**
   * 瓦片底图（来自 `config.maps` 的根地图）。给了它、并且 `site` 配了
   * `placement` + `ground`，才会铺影像地面；否则一切照旧。
   */
  basemap?: BasemapConfig;
  /**
   * 漫游模式（`/roam`，`docs/project/ROAM-PLAN-A.md` §2 S4a）：地面不再按
   * `ground.radius` 铺一块固定的，而是**跟着相机视野流式铺**——相机移到哪里、
   * 哪一层的瓦片就补到哪里，退出视野的瓦片释放掉。相机也不受二维地图的
   * `minZoom/maxZoom` 约束：层级由「屏幕上这米有多宽」实时算出来。
   */
  roam?: boolean;
  /**
   * 起飞交接（`docs/project/ROAM-PLAN-A.md` §2 S5）：点热点后先让相机飞到该热点上方，
   * 飞满这个毫秒数再把 `onActivate` 交出去（交出去 = 切路由去全景）。
   * 缺省 `0` = 立刻交出去，`/site` 的既有行为一步不变。
   */
  takeoffMs?: number;
  /**
   * 外部要求某台设备「起飞交接」（热点卡片点一下就是它）。与点场景里的热点走同一条路，
   * 只是不重建场景——同一个值不会重复触发。
   */
  focusHotspotId?: string | null;
}

export type SiteSceneComponent = ComponentType<SiteSceneProps>;

/**
 * 两种影像地面（固定的 `GroundLayer`、流式的 `GroundStreamer`）对场景一侧的共同接口：
 * 标定面板只需要这三个动作，不必知道当下铺的是哪一种。
 */
interface GroundSurface {
  group: THREE.Group;
  setElevation(value: number): void;
  setOpacity(value: number): void;
  dispose(): void;
}

function fitDistance(size: THREE.Vector3, fovDegrees: number, aspect: number) {
  const vertical = THREE.MathUtils.degToRad(fovDegrees);
  const heightDistance = size.y / (2 * Math.tan(vertical / 2));
  const widthDistance = size.x / (2 * Math.tan(vertical / 2) * Math.max(0.2, aspect));
  return Math.max(heightDistance, widthDistance, size.z * 0.6) * 1.25;
}

export const SiteScene = memo(function SiteScene({
  site,
  basemap,
  roam = false,
  takeoffMs = 0,
  focusHotspotId = null,
  markers,
  view,
  onActivate,
  onProgress,
  onError,
  onIssues,
  onReady,
  retryToken = 0,
}: SiteSceneProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const markerRefs = useRef(new Map<string, HTMLButtonElement>());
  const viewRef = useRef(view);
  const activateRef = useRef(onActivate);
  /**
   * 真正「交出去」的动作。点热点时走这里而不是直接调 `onActivate`：
   * 配了 `takeoffMs` 就先飞一段（S5），飞完再切路由。
   */
  const requestActivateRef = useRef<((hotspotId: string) => void) | null>(null);
  const progressRef = useRef(onProgress);
  const errorRef = useRef(onError);
  const issuesRef = useRef(onIssues);
  const readyRef = useRef(onReady);
  const [progress, setProgress] = useState<number | null>(null);
  const [preparing, setPreparing] = useState(false);
  const [ready, setReady] = useState(false);
  const [loadError, setLoadError] = useState('');
  const [retryAttempt, setRetryAttempt] = useState(0);

  /*
   * 配准标定（`?calibrate=1`，`docs/project/ROAM-PLAN-A.md` §2 S3）。
   * 三个滑杆要即时看到结果，但绝不能跟着重建场景——32 MB 的模型重下一次是不可接受的，
   * 所以 `storeCalibration` 由主 effect 在模型加载完时挂上，滑杆只调它改矩阵。
   */
  const calibrating = useMemo(
    () => typeof window !== 'undefined' && new URLSearchParams(window.location.search).has('calibrate'),
    [],
  );
  const draft = usePlacementDraft(site);
  const [wireframe, setWireframe] = useState(false);
  const [canWriteBack, setCanWriteBack] = useState(false);
  const [writeBack, setWriteBack] = useState<'idle' | 'busy' | 'done' | 'error'>('idle');
  const calibrationRef = useRef<{
    placement(next: PlacementConfig, overlayOpacity: number): void;
    wireframe(on: boolean): void;
  } | null>(null);

  viewRef.current = view;
  activateRef.current = onActivate;

  /*
   * 热点卡片点一下 = 要求起飞交接。单独一个 effect：只碰 `requestActivateRef`，
   * 不把 `focusHotspotId` 塞进主 effect 的依赖里（那会为了点一个热点重建整个 WebGL 场景）。
   */
  const focusedRef = useRef<string | null>(null);
  useEffect(() => {
    if (!focusHotspotId) { focusedRef.current = null; return; }
    if (focusedRef.current === focusHotspotId) return;
    focusedRef.current = focusHotspotId;
    requestActivateRef.current?.(focusHotspotId);
    // `requestActivateRef` 是 ref，不进依赖表。
  }, [focusHotspotId]);
  progressRef.current = onProgress;
  errorRef.current = onError;
  issuesRef.current = onIssues;
  readyRef.current = onReady;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    let disposed = false;
    let animationFrame = 0;
    let dirty = true;
    let ready = false;
    let loaded: LoadedSiteModel | null = null;
    let contextIsLost = false;
    let restoreFallback = 0;
    let lastView = '';
    let lastReset = -1;
    let tween: { from: THREE.Vector3; to: THREE.Vector3; targetFrom: THREE.Vector3; targetTo: THREE.Vector3; t: number; seconds?: number } | null = null;
    /** 起飞交接（S5）里那笔「飞完再切路由」的定时器，卸载时要撤掉，否则会跳到已经不存在的页面。 */
    let takeoffTimer = 0;
    /** 模型下载失败后的自动重试（见下面 catch 里的理由），卸载时要撤掉。 */
    let retryTimer = 0;
    let autoRetry = 0;
    const clock = new THREE.Clock();
    // 天空/雾/灯光统一走 activeScenePalette()（见 shared/scenePalette.ts）。
    const palette = activeScenePalette();
    const maxPixelRatio = Math.min(window.devicePixelRatio, 1.5);
    // 手机上**从 1.0 起步**，再由下面的自适应在 45 帧后往上加：场地模型一帧要提交
    // 900 万三角面、400 次 draw call，1.5 倍像素比意味着 2.25 倍的填充量，而手机第一次拖动的
    // 那几秒正是模型刚下完、GPU 最吃紧的时候（自适应要 45 帧才降下来，8fps 下就是 5.6 秒）。
    // 先保守、再升档，比先拉满、再降档更不容易在"第一次交互"就卡住。
    const lowPowerHost = navigator.maxTouchPoints > 0 || window.innerWidth < 700;
    let pixelRatio = lowPowerHost ? Math.min(maxPixelRatio, 1) : maxPixelRatio;
    let renderedFrames = 0;
    let renderedSeconds = 0;

    setProgress(null);
    setPreparing(false);
    setReady(false);
    setLoadError('');

    let renderer: THREE.WebGLRenderer;
    try {
      renderer = new THREE.WebGLRenderer({ antialias: false, alpha: false, powerPreference: 'high-performance' });
    } catch {
      const message = '无法启动三维查看器，请使用支持 WebGL 的浏览器';
      setLoadError(message);
      errorRef.current?.(message);
      return;
    }
    renderer.setClearColor(palette.site.sky, 1);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = palette.site.exposure;
    renderer.domElement.setAttribute('aria-label', '武高所户外试验场三维场地模型。拖动旋转，滚轮或双指缩放，点击设备进入三维详情。');
    host.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(palette.site.sky);
    // 默认取景距离约 370 m（整场 388 × 137 m），雾的近端必须比它更远，
    // 否则一进场整片场地都是灰的；远端留到 2.2 km，只让最远的那一角淡出去。
    scene.fog = new THREE.Fog(
      new THREE.Color(palette.site.sky),
      roam ? palette.site.fog.near * 2.4 : palette.site.fog.near,
      // 漫游要把整院区连同周边一起看进来（一两公里），雾的远端得跟着推出去，
      // 否则一拉远整片地面就被雾抹平了。
      roam ? Math.max(palette.site.fog.far, 6000) : palette.site.fog.far,
    );
    // 场地跨度近 400 米，近裁剪面必须放大（1 厘米级近裁剪会让 400 米外的深度精度崩掉）。
    const camera = new THREE.PerspectiveCamera(45, 1, 0.6, roam ? 6000 : 2600);
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = SITE_DAMPING_BASE;
    controls.enablePan = true;
    controls.screenSpacePanning = true;
    // 桌面端操作：左键旋转、**中键平移**、右键也保留平移（老习惯），滚轮缩放。
    // OrbitControls 默认是中键 dolly、右键平移，这里按需求把平移挪到中键。
    controls.mouseButtons = { LEFT: THREE.MOUSE.ROTATE, MIDDLE: THREE.MOUSE.PAN, RIGHT: THREE.MOUSE.PAN };
    controls.minDistance = 3;
    controls.maxDistance = roam ? 2400 : 900;
    controls.maxPolarAngle = Math.PI * 0.495;
    controls.zoomSpeed = 0.9;
    controls.rotateSpeed = SITE_ROTATE_SPEED;
    controls.addEventListener('change', () => { dirty = true; });

    const pmrem = new THREE.PMREMGenerator(renderer);
    const room = new RoomEnvironment();
    const environment = pmrem.fromScene(room, 0.05);
    scene.environment = environment.texture;
    scene.environmentIntensity = palette.site.environmentIntensity;
    room.dispose();
    pmrem.dispose();
    scene.add(new THREE.HemisphereLight(palette.site.hemisphere.sky, palette.site.hemisphere.ground, palette.site.hemisphere.intensity));
    const keyLight = new THREE.DirectionalLight(palette.site.key.color, palette.site.key.intensity);
    keyLight.position.set(...palette.site.key.position);
    scene.add(keyLight);
    const fillLight = new THREE.DirectionalLight(palette.site.fill.color, palette.site.fill.intensity);
    fillLight.position.set(...palette.site.fill.position);
    scene.add(fillLight);

    const modelRoot = new THREE.Group();
    modelRoot.name = 'site-root';
    scene.add(modelRoot);

    /*
     * 影像地面（`docs/project/ROAM-PLAN-A.md` §2 S2 / S4a）。三件事同时具备才铺：
     * `placement`（锚点）、`ground`（层级与半径）、调用方递进来的瓦片底图。
     * 缺任何一件都完全保持今天的样子——既有 `/site` 的表现不因这次改动而变。
     *
     * 两种铺法共用同一套对外动作（`setElevation` / `setOpacity` / `dispose`），
     * 所以标定面板不必知道现在是哪一种：
     * - 默认（`/site`）：`ground.radius` 圈定的固定一块，铺好就不动；
     * - 漫游（`/roam`）：跟着相机视野流式增删（见 `GroundStreamer.ts`）。
     */
    let ground: GroundSurface | undefined;
    let streamer: GroundStreamer | undefined;
    const groundElevation = site.placement ? site.placement.elevationM - GROUND_DROP_M : 0;
    if (site.placement && site.ground && basemap) {
      if (roam) {
        streamer = createGroundStreamer({
          anchor: site.placement.anchor,
          basemap,
          overlayOpacity: site.ground.overlayOpacity,
          elevation: groundElevation,
          // 场地场景是按需渲染的（`dirty` 才画一帧），瓦片是异步贴上的，必须由它置脏。
          onUpdate: () => { dirty = true; },
        });
        ground = streamer;
      } else {
        ground = createGroundLayer({
          anchor: site.placement.anchor,
          zoom: site.ground.zoom,
          radius: site.ground.radius,
          overlayOpacity: site.ground.overlayOpacity,
          basemap,
          elevation: groundElevation,
          onUpdate: () => { dirty = true; },
        });
      }
      scene.add(ground.group);
    }

    // 性能探针（只有 `?perf=1` 时挂载）：场地是全站最重的一屏，验证时要能读到真实的
    // draw call / 贴图显存 / 三角面数，而不是只看帧率。
    if (new URLSearchParams(window.location.search).get('perf') === '1') {
      (window as unknown as { __museumSite?: unknown }).__museumSite = { renderer, scene, camera, modelRoot, controls };
    }

    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();
    const tap = new PointerTap();

    /*
     * 漫游时地面铺到哪里：把屏幕均匀打 5×5 条射线，与地面平面求交，取交点的经纬范围。
     * `metersPerPixel` 由窗口宽度除以画布像素宽得到——瓦片层级就是按它定的，
     * 所以「拉远看全貌」时层级自动降、贴到设备旁边时自动升，不受二维地图的
     * `minZoom/maxZoom` 约束（`docs/project/ROAM-PLAN-A.md` §2 S4a）。
     */
    const groundPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
    const hitPoint = new THREE.Vector3();
    const groundView = (): { window: GroundWindow; metersPerPixel: number } | null => {
      if (!site.placement) return null;
      groundPlane.constant = -groundElevation;
      let west = Infinity;
      let east = -Infinity;
      let south = Infinity;
      let north = -Infinity;
      let hits = 0;
      const samples = 5;
      for (let iy = 0; iy < samples; iy += 1) {
        for (let ix = 0; ix < samples; ix += 1) {
          pointer.set((ix / (samples - 1)) * 2 - 1, (iy / (samples - 1)) * 2 - 1);
          raycaster.setFromCamera(pointer, camera);
          if (!raycaster.ray.intersectPlane(groundPlane, hitPoint)) continue;
          hits += 1;
          const enu = enuFromScene(hitPoint);
          west = Math.min(west, enu.east);
          east = Math.max(east, enu.east);
          south = Math.min(south, enu.north);
          north = Math.max(north, enu.north);
        }
      }
      // 一条都没打到（相机朝向天空 / 地平线以上）就什么都不动，别把铺好的地面全撤了。
      if (hits < 2) return null;
      // 贴着地面平视时窗口会退化成一条线，给个下限，免得每帧换一批瓦片来回抖。
      const minimum = 120;
      if (east - west < minimum) {
        const center = (east + west) / 2;
        west = center - minimum / 2;
        east = center + minimum / 2;
      }
      if (north - south < minimum) {
        const center = (north + south) / 2;
        south = center - minimum / 2;
        north = center + minimum / 2;
      }
      return {
        window: { west, east, south, north },
        metersPerPixel: Math.max(0.05, (east - west) / Math.max(1, host.clientWidth)),
      };
    };

    // 中键平移的配套处理：Chrome 在画布上按中键会弹出"自动滚动"圆盘抢走拖拽，
    // OrbitControls 自己不会 preventDefault（它只监听 pointer 事件），这里按掉 mousedown 的默认行为。
    const suppressMiddleButtonDefault = (event: MouseEvent) => {
      if (event.button === 1) event.preventDefault();
    };
    renderer.domElement.addEventListener('mousedown', suppressMiddleButtonDefault);
    renderer.domElement.addEventListener('auxclick', suppressMiddleButtonDefault);

    const setCamera = (target: THREE.Vector3, position: THREE.Vector3) => {
      controls.target.copy(target);
      camera.position.copy(position);
      controls.update();
      dirty = true;
    };

    const fitAll = () => {
      const bounds = new THREE.Box3().setFromObject(modelRoot);
      if (bounds.isEmpty()) return;
      const center = bounds.getCenter(new THREE.Vector3());
      const size = bounds.getSize(new THREE.Vector3());
      const distance = fitDistance(size, camera.fov, camera.aspect);
      // 默认视线：从场地南侧偏东俯视（场地按 y 轴铺开，z 向上）。
      const direction = new THREE.Vector3(0.45, 0.52, 0.72).normalize();
      const position = center.clone().addScaledVector(direction, distance);
      setCamera(center, position);
    };

    const project = (anchor: THREE.Vector3) => {
      const point = anchor.clone().project(camera);
      const width = host.clientWidth;
      const height = host.clientHeight;
      return {
        x: (point.x * 0.5 + 0.5) * width,
        y: (-point.y * 0.5 + 0.5) * height,
        visible: point.z < 1 && point.x > -1.35 && point.x < 1.35 && point.y > -1.35 && point.y < 1.35,
      };
    };

    /**
     * 面板遮挡：标记层在画布之上、面板之下，被右侧设备列表/工具条/身份区盖住的标记只剩下
     * 一条白边从卡片边缘探出来，看着像渲染错位（实测 844×390 时 93% 被卡片盖住）。
     * 这类标记本来也点不到，所以整块隐藏；旋转视角离开面板后自动恢复。
     */
    const overlayRects: Array<{ left: number; top: number; right: number; bottom: number }> = [];
    const markerSizes = new Map<string, { width: number; height: number }>();
    const refreshOverlays = () => {
      overlayRects.length = 0;
      markerSizes.clear();
      for (const [id, element] of markerRefs.current) {
        markerSizes.set(id, { width: element.offsetWidth, height: element.offsetHeight });
      }
      const parent = host.parentElement;
      if (!parent) return;
      const hostRect = host.getBoundingClientRect();
      for (const name of ['site-tools', 'site-identity']) {
        const element = parent.querySelector<HTMLElement>(`.${name}`);
        if (!element || element.offsetParent === null) continue;
        const rect = element.getBoundingClientRect();
        if (!rect.width || !rect.height) continue;
        overlayRects.push({
          left: rect.left - hostRect.left,
          top: rect.top - hostRect.top,
          right: rect.right - hostRect.left,
          bottom: rect.bottom - hostRect.top,
        });
      }
      // 标定面板在 `.site-scene` **里面**（不在它的父层），所以单独量一次：
      // 被面板盖住的标记同样只剩一条边，看着像渲染错位。
      const calibration = host.querySelector<HTMLElement>('.site-calibration');
      if (calibration && calibration.offsetParent !== null) {
        const rect = calibration.getBoundingClientRect();
        if (rect.width && rect.height) {
          overlayRects.push({
            left: rect.left - hostRect.left,
            top: rect.top - hostRect.top,
            right: rect.right - hostRect.left,
            bottom: rect.bottom - hostRect.top,
          });
        }
      }
    };
    /** 标记盒子被面板盖住的比例。 */
    const coveredRatio = (box: { left: number; top: number; right: number; bottom: number }) => {
      const area = Math.max(1, (box.right - box.left) * (box.bottom - box.top));
      let covered = 0;
      for (const rect of overlayRects) {
        const wide = Math.min(box.right, rect.right) - Math.max(box.left, rect.left);
        const tall = Math.min(box.bottom, rect.bottom) - Math.max(box.top, rect.top);
        if (wide > 0 && tall > 0) covered += wide * tall;
      }
      return covered / area;
    };

    const updateMarkers = () => {
      if (!loaded) return;
      const hostWidth = host.clientWidth;
      for (const hotspot of loaded.hotspots) {
        const element = markerRefs.current.get(hotspot.config.id);
        if (!element) continue;
        const { x, y, visible } = project(hotspot.anchor);
        element.style.transform = `translate(-50%, -100%) translate(${Math.round(x)}px, ${Math.round(y)}px)`;
        const size = markerSizes.get(hotspot.config.id);
        /*
         * 名称标签默认以锚点为中心，靠近左右边缘时会被屏幕切掉。
         * 设备入口现在就是这些标记（底部设备栏已删），名称被切等于"这台设备不知道叫什么"，
         * 所以这里把**标签**推回画面内（只动标签，不动 pin：pin 必须留在真实锚点上）。
         */
        if (size && size.width > 4) {
          const half = size.width / 2;
          const shift = x - half < 0 ? half - x
            : x + half > hostWidth ? hostWidth - half - x
              : 0;
          element.style.setProperty('--marker-label-shift', `${Math.round(shift)}px`);
        }
        // 尺寸还没量出来（首帧 / jsdom 里布局为 0）时不做遮挡判断，只按可见性显示。
        const occluded = size && size.width > 4 && size.height > 4
          ? coveredRatio({ left: x - size.width / 2, right: x + size.width / 2, top: y - size.height, bottom: y }) >= 0.5
          : false;
        element.style.visibility = visible && !occluded ? 'visible' : 'hidden';
      }
    };

    /*
     * 标定口子：把面板上的航向 / 高度 / 缩放 / 注记透明度即时作用到**已经加载**的场景。
     * `prepareStaticRoot` 已经把模型根的 `matrixAutoUpdate` 关掉，所以改完必须显式
     * `updateMatrixWorld(true)`，否则热点锚点还停在旧变换上（标记会飘在错误的位置）。
     */
    const applyCalibration = (next: PlacementConfig, overlayOpacity: number) => {
      if (!loaded) return;
      const transform = placementTransform(next);
      modelRoot.position.set(...transform.position);
      modelRoot.rotation.y = transform.rotationY;
      modelRoot.scale.setScalar(transform.scale);
      /*
       * 两行都不能省：`prepareStaticRoot` 把整棵树的 `matrixAutoUpdate` 关掉了，
       * 于是 `updateMatrixWorld(true)` 不会重算**本层**矩阵（它只在 `matrixAutoUpdate` 为真时
       * 调 `updateMatrix()`），必须自己先 `updateMatrix()`。少了这一行的症状很隐蔽：
       * `modelRoot.rotation.y` 读出来是新值，模型却纹丝不动，热点标记一个都不挪。
       */
      modelRoot.updateMatrix();
      modelRoot.updateMatrixWorld(true);
      const resolved = resolveSiteHotspots(modelRoot, site.hotspots);
      loaded.hotspots = resolved.hotspots;
      loaded.issues = resolved.issues;
      ground?.setElevation(next.elevationM - GROUND_DROP_M);
      ground?.setOpacity(overlayOpacity);
      refreshOverlays();
      updateMarkers();
      dirty = true;
    };

    /** 线框模式：场地模型自带地面，切成线框才看得见下面的影像有没有对上。改完能还原。 */
    const originalWireframe = new Map<THREE.Material, boolean>();
    const applyWireframe = (on: boolean) => {
      if (!loaded) return;
      loaded.root.traverse(object => {
        const material = (object as THREE.Mesh).material;
        const list = Array.isArray(material) ? material : material ? [material] : [];
        for (const item of list) {
          if (!originalWireframe.has(item)) {
            originalWireframe.set(item, (item as THREE.MeshStandardMaterial).wireframe === true);
          }
          const wire = item as THREE.MeshStandardMaterial;
          wire.wireframe = on || originalWireframe.get(item) === true;
          wire.needsUpdate = true;
        }
      });
      dirty = true;
    };
    const storeCalibration = () => {
      calibrationRef.current = { placement: applyCalibration, wireframe: applyWireframe };
    };

    const prepareStaticRoot = (root: THREE.Object3D) => {
      root.traverse(object => {
        object.updateMatrix();
        object.matrixAutoUpdate = false;
        const mesh = object as THREE.Mesh;
        if (mesh.isMesh) mesh.geometry.computeBoundingSphere();
      });
      root.updateMatrixWorld(true);
    };

    // 主指针是不是手指（`(pointer: coarse)`）。带触摸屏的笔记本同时有鼠标，主指针仍是 fine，不该被放大。
    const coarsePointer = detectCoarsePointer();
    const resize = () => {
      refreshOverlays();
      if (!host.clientWidth || !host.clientHeight) return;
      renderer.setPixelRatio(pixelRatio);
      camera.aspect = host.clientWidth / host.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(host.clientWidth, host.clientHeight);
      // 每像素弧度 = rotateSpeed * 2π / 画布高：手指设备上按画布高度补回桌面手感（平板竖屏 +34%），
      // 横竖屏切换会改画布高，所以放在 resize 里而不是初始化一次。
      controls.rotateSpeed = SITE_ROTATE_SPEED * coarseRotateSpeedScale(host.clientHeight, coarsePointer);
      dirty = true;
    };
    const observer = new ResizeObserver(resize);
    observer.observe(host);
    // 面板自己变形（例如身份区多出一行提示、设备列表高度变化）也要重算遮挡矩形，
    // 否则缓存的矩形会过期，标记可能该隐藏的没隐藏。
    const panelObserver = new ResizeObserver(() => refreshOverlays());
    for (const selector of ['site-tools', 'site-identity']) {
      const element = host.parentElement?.querySelector(selector);
      if (element) panelObserver.observe(element);
    }
    resize();

    loadSiteModel(site, {
      onProgress: value => {
        if (disposed) return;
        // GLTFLoader 的 100% 仅代表文件下载完成；Draco 解码和首帧渲染仍需时间。
        if (value >= 100) setPreparing(true);
        else setProgress(Math.max(0, Math.min(99, value)));
        progressRef.current?.(Math.min(99, value));
      },
    }).then(model => {
      if (disposed) {
        disposeModelRoot(model.root);
        return;
      }
      setPreparing(true);
      loaded = model;
      modelRoot.add(model.root);
      /*
       * 地理配准：场景原点就是 `placement.anchor`，所以模型根只需要高度 / 航向 / 缩放三个量。
       * 必须在 `prepareStaticRoot` 之前落地——它会把整棵树的矩阵冻结（`matrixAutoUpdate = false`），
       * 之后再改位置只能靠显式 `updateMatrixWorld(true)` 才生效，那是自找麻烦。
       * 门槛与地面同一个（`basemap`）：配准属于「地理配准模式」，旧 UI 的 `/devices`
       * 与 `?ui=next` 不传 `basemap`，所以哪怕配置里写了航向，它们也不会被转过去。
       */
      if (basemap && site.placement) {
        const transform = placementTransform(site.placement);
        modelRoot.position.set(...transform.position);
        modelRoot.rotation.y = transform.rotationY;
        modelRoot.scale.setScalar(transform.scale);
      }
      // 静态场景：关掉每帧的世界矩阵重算（1447 个网格时这是实打实的 CPU 开销），
      // 这里一次性算好即可——场地模型不会动。
      prepareStaticRoot(modelRoot);
      modelRoot.updateMatrixWorld(true);
      issuesRef.current?.(model.issues.length);
      ready = true;
      fitAll();
      // 标记尺寸与面板矩形要在同一帧刷新（面板布局此时已定型），再据此决定标记是否被盖住。
      refreshOverlays();
      updateMarkers();
      dirty = true;
      // 此时才谈得上标定：面板上再动滑杆就有入口可用。
      storeCalibration();
      // 先画出完整模型，再撤下不透明的加载层，避免闪过一帧空场景。
      renderer.render(scene, camera);
      dirty = false;
      progressRef.current?.(100);
      setReady(true);
      onReady?.();
    }).catch(error => {
      if (disposed) return;
      const message = error instanceof Error ? error.message : '场地模型加载失败';
      // 场地模型是**一个 33 MB 的整包**下载（`/content/*` 由浏览器直接取，不走 Service Worker），
      // 手机网络与 GitHub Pages 都会偶发中断：2026-10-19 线上实测出现过
      // `net::ERR_CONNECTION_CLOSED`，页面就停在"场地模型加载失败"，用户只能自己按「重新加载」。
      // 失败发生在传输早期、重试成本很低，所以这里自动重试两次（1.5s / 3s 递增退避）再报错。
      if (autoRetry < SITE_LOAD_RETRIES) {
        autoRetry += 1;
        retryTimer = window.setTimeout(() => {
          retryTimer = 0;
          if (!disposed) setRetryAttempt(value => value + 1);
        }, 1500 * autoRetry);
        return;
      }
      setLoadError(message);
      errorRef.current?.(message);
    });

    const pick = (clientX: number, clientY: number) => {
      if (!ready || !loaded) return null;
      // 只对"带热点的节点"做射线检测：场地模型合并后环境是一个上百万面的大网格，
      // 整场拾取每次都要几十毫秒；而这里真正只关心"有没有点到某台设备"。
      const roots = loaded.hotspots.flatMap(hotspot => hotspot.objects);
      if (!roots.length) return null;
      const rect = renderer.domElement.getBoundingClientRect();
      pointer.set((clientX - rect.left) / rect.width * 2 - 1, -(clientY - rect.top) / rect.height * 2 + 1);
      raycaster.setFromCamera(pointer, camera);
      for (const hit of raycaster.intersectObjects(roots, true)) {
        const id = findHotspotId(hit.object, modelRoot, loaded.hotspots);
        if (id) return id;
      }
      return null;
    };

    const pointerDown = (event: PointerEvent) => {
      tap.down(event.pointerId, event.clientX, event.clientY, event.pointerType === 'touch' ? 12 : 5);
    };
    let lastHoverPick = 0;
    /**
     * 起飞交接（S5）：相机从当前位置飞到热点上方，同时把视线收到热点锚点上；
     * 飞满 `takeoffMs` 才 `onActivate`（切路由去全景）。`takeoffMs === 0` 时立刻交出去。
     */
    const requestActivate = (id: string) => {
      const hotspot = loaded?.hotspots.find(item => item.config.id === id);
      if (!takeoffMs || !hotspot) { activateRef.current(id); return; }
      const anchor = hotspot.anchor.clone();
      // 「站到设备跟前」的取景：南侧偏东、抬高一点，距离按场地尺度取一个固定值（48 m）。
      const distance = 48;
      const direction = new THREE.Vector3(0.4, 0.5, 0.85).normalize();
      tween = {
        from: camera.position.clone(),
        to: anchor.clone().addScaledVector(direction, distance),
        targetFrom: controls.target.clone(),
        targetTo: anchor,
        t: 0,
        seconds: Math.max(0.2, takeoffMs / 1000),
      };
      dirty = true;
      takeoffTimer = window.setTimeout(() => activateRef.current(id), takeoffMs);
    };
    requestActivateRef.current = requestActivate;

    const pointerMove = (event: PointerEvent) => {
      tap.move(event.pointerId, event.clientX, event.clientY);
      if (event.pointerType === 'touch' || event.buttons !== 0) return;
      const now = performance.now();
      // 拾取只针对设备节点（见 pick），成本与场地环境的面数无关；这里仍限流到 8Hz。
      if (now - lastHoverPick < 120) return;
      lastHoverPick = now;
      renderer.domElement.style.cursor = pick(event.clientX, event.clientY) ? 'pointer' : 'grab';
    };
    const pointerUp = (event: PointerEvent) => {
      if (!tap.up(event.pointerId, event.clientX, event.clientY)) return;
      const id = pick(event.clientX, event.clientY);
      if (id) requestActivate(id);
    };
    const pointerCancel = (event: PointerEvent) => tap.cancel(event.pointerId);
    renderer.domElement.addEventListener('pointerdown', pointerDown);
    renderer.domElement.addEventListener('pointermove', pointerMove);
    renderer.domElement.addEventListener('pointerup', pointerUp);
    renderer.domElement.addEventListener('pointercancel', pointerCancel);

    const contextLost = (event: Event) => {
      event.preventDefault();
      contextIsLost = true;
      renderer.domElement.style.opacity = '0';
      if (restoreFallback === 0) {
        restoreFallback = window.setTimeout(() => {
          restoreFallback = 0;
          if (disposed) return;
          contextIsLost = false;
          setRetryAttempt(value => value + 1);
        }, 600);
      }
    };
    const contextRestored = () => {
      contextIsLost = false;
      if (restoreFallback !== 0) {
        window.clearTimeout(restoreFallback);
        restoreFallback = 0;
      }
      setRetryAttempt(value => value + 1);
    };
    renderer.domElement.addEventListener('webglcontextlost', contextLost);
    renderer.domElement.addEventListener('webglcontextrestored', contextRestored);

    /** 俯视：从正上方看整场（场地是平面布局，俯视最适合找设备）。 */
    const topTween = () => {
      const bounds = new THREE.Box3().setFromObject(modelRoot);
      const center = bounds.getCenter(new THREE.Vector3());
      const size = bounds.getSize(new THREE.Vector3());
      const distance = fitDistance(size, camera.fov, camera.aspect);
      const position = center.clone().add(new THREE.Vector3(0, 0.02, 1).multiplyScalar(distance));
      return {
        from: camera.position.clone(),
        to: position,
        targetFrom: controls.target.clone(),
        targetTo: center,
        t: 0,
      };
    };

    const isoTween = () => {
      const bounds = new THREE.Box3().setFromObject(modelRoot);
      const center = bounds.getCenter(new THREE.Vector3());
      const size = bounds.getSize(new THREE.Vector3());
      const distance = fitDistance(size, camera.fov, camera.aspect);
      const position = center.clone().addScaledVector(new THREE.Vector3(0.45, 0.52, 0.72).normalize(), distance);
      return {
        from: camera.position.clone(),
        to: position,
        targetFrom: controls.target.clone(),
        targetTo: center,
        t: 0,
      };
    };

    /** 把 view 状态翻译成相机动作：复位瞬移，俯视/等轴/聚焦走补间。 */
    const applyView = () => {
      const state = viewRef.current;
      if (!ready) return;
      if (state.reset !== lastReset) {
        lastReset = state.reset;
        lastView = state.top ? 'top' : 'iso';
        tween = null;
        if (state.top) {
          const target = topTween();
          setCamera(target.targetTo, target.to);
        } else {
          fitAll();
        }
      } else if (state.top !== (lastView === 'top')) {
        lastView = state.top ? 'top' : 'iso';
        tween = state.top ? topTween() : isoTween();
      }
      // "聚焦到某台设备"（原设备栏的准星）已随设备栏一起删掉：设备入口变成场地标记本身，
      // 点标记直接进设备页，不再需要一段把相机拉到设备前的补间。
    };

    const animate = () => {
      if (disposed) return;
      animationFrame = requestAnimationFrame(animate);
      if (contextIsLost) return;
      // 切到底部导航其它栏目时本页仍然挂载（模型不重载，切回来不用等），
      // 但外层槽位被 hidden 折叠成 0×0：这一帧直接跳过，别在看不见的画布上白渲染。
      // delta 本来就上限 0.05，所以切回来也不会"跳一帧"。
      if (!host.clientWidth || !host.clientHeight) return;
      const frameSeconds = clock.getDelta();
      const delta = Math.min(frameSeconds, 0.05);
      const state = viewRef.current;
      applyView();
      if (tween) {
        tween.t = Math.min(1, tween.t + delta / (tween.seconds ?? 0.75));
        const eased = tween.t < 0.5 ? 2 * tween.t * tween.t : 1 - 2 * (1 - tween.t) * (1 - tween.t);
        camera.position.lerpVectors(tween.from, tween.to, eased);
        controls.target.lerpVectors(tween.targetFrom, tween.targetTo, eased);
        dirty = true;
        if (tween.t >= 1) tween = null;
      }
      controls.autoRotate = ready && state.rotate;
      controls.autoRotateSpeed = 0.35;
      // OrbitControls 的惯性衰减是**按帧**算的（不是按时间），低帧率手机上会被拖成好几秒，
      // 手感就是"跟不上手 / 松手后还在飘"。这里按真实帧长把每帧衰减换算到 60fps 等价系数。
      // 注意传的是**未截断**的 `frameSeconds`：`delta` 被夹到 0.05 是为了补间稳定，
      // 拿它换算会在 8fps 的手机上少补一半（实测帧长 0.125s 会被当成 0.05s）。
      // 依据与推导见 shared/orbitDamping.ts。
      controls.dampingFactor = dampingForFrame(SITE_DAMPING_BASE, frameSeconds);
      controls.update();
      if (controls.autoRotate) dirty = true;
      // 漫游：地面跟着相机走。相机没动时窗口与上一帧相同，`update()` 是一遍空对账，很便宜。
      if (streamer) {
        const canvasWidth = host.clientWidth;
        const view = canvasWidth ? groundView() : null;
        if (view) {
          const before = streamer.stats.mounted + streamer.stats.released;
          streamer.update(view);
          if (streamer.stats.mounted + streamer.stats.released !== before) dirty = true;
        }
      }
      updateMarkers();
      if (dirty) {
        renderer.render(scene, camera);
        dirty = false;
        // Keep the complete geometry on screen. On a slow phone only the
        // framebuffer resolution changes, so buildings never pop in or out.
        if (ready && frameSeconds < 0.2 && maxPixelRatio > 1 && (navigator.maxTouchPoints > 0 || host.clientWidth < 700)) {
          renderedFrames += 1;
          renderedSeconds += frameSeconds;
          if (renderedFrames >= 45) {
            const averageMs = renderedSeconds * 1000 / renderedFrames;
            const next = averageMs > 36
              ? Math.max(1, pixelRatio - 0.25)
              : averageMs < 22 ? Math.min(maxPixelRatio, pixelRatio + 0.25) : pixelRatio;
            renderedFrames = 0;
            renderedSeconds = 0;
            if (next !== pixelRatio) {
              pixelRatio = next;
              renderer.setPixelRatio(pixelRatio);
              renderer.setSize(host.clientWidth, host.clientHeight, false);
              dirty = true;
            }
          }
        }
      }
    };
    animate();

    return () => {
      disposed = true;
      calibrationRef.current = null;
      requestActivateRef.current = null;
      if (takeoffTimer !== 0) window.clearTimeout(takeoffTimer);
      if (retryTimer !== 0) window.clearTimeout(retryTimer);
      cancelAnimationFrame(animationFrame);
      if (restoreFallback !== 0) window.clearTimeout(restoreFallback);
      observer.disconnect();
      panelObserver.disconnect();
      controls.dispose();
      renderer.domElement.removeEventListener('pointerdown', pointerDown);
      renderer.domElement.removeEventListener('pointermove', pointerMove);
      renderer.domElement.removeEventListener('pointerup', pointerUp);
      renderer.domElement.removeEventListener('pointercancel', pointerCancel);
      renderer.domElement.removeEventListener('webglcontextlost', contextLost);
      renderer.domElement.removeEventListener('webglcontextrestored', contextRestored);
      renderer.domElement.removeEventListener('mousedown', suppressMiddleButtonDefault);
      renderer.domElement.removeEventListener('auxclick', suppressMiddleButtonDefault);
      if (ground) ground.dispose();
      if (loaded) disposeModelRoot(loaded.root);
      environment.dispose();
      renderer.dispose();
      renderer.domElement.remove();
    };
  }, [site, basemap, roam, retryAttempt, retryToken]);

  // 滑杆即时生效：只改矩阵/材质，不重建场景（重建等于把 32 MB 的模型再下一次）。
  useEffect(() => {
    calibrationRef.current?.placement(draft.placement, draft.ground.overlayOpacity);
  }, [draft.placement, draft.ground.overlayOpacity]);

  useEffect(() => {
    calibrationRef.current?.wireframe(wireframe);
  }, [wireframe]);

  // 生产/静态托管没有这个接口，`probeConfigWriter()` 为假，面板就不显示「写回 museum.json」。
  useEffect(() => {
    if (!calibrating || !basemap) return;
    let alive = true;
    void probeConfigWriter().then(available => {
      if (alive) setCanWriteBack(available);
    });
    return () => {
      alive = false;
    };
  }, [calibrating, basemap]);

  const writeBackPlacement = useCallback(async () => {
    setWriteBack('busy');
    const result = await writeConfigDefaults({
      siteModel: { placement: draft.placement, ground: draft.ground },
    });
    setWriteBack(result.ok ? 'done' : 'error');
  }, [draft.placement, draft.ground]);

  return (
    <div className="site-scene" ref={hostRef}>
      <div className="site-marker-layer">
        {markers.map(marker => (
          <button
            key={marker.id}
            type="button"
            className="site-marker"
            ref={element => {
              if (element) markerRefs.current.set(marker.id, element);
              else markerRefs.current.delete(marker.id);
            }}
            style={{ visibility: 'hidden' }}
            aria-label={`${marker.label}：查看三维模型`}
            onClick={() => (requestActivateRef.current ?? onActivate)(marker.id)}
          >
            <span className="site-marker-pin" aria-hidden="true" />
            <span className="site-marker-label">
              <strong>{marker.label}</strong>
              {marker.description && <small>{marker.description}</small>}
            </span>
          </button>
        ))}
      </div>
      {!ready && !loadError && (
        <div className="site-loading" role="status">
          <div className="site-loading-panel">
            <strong>正在加载{site.name}</strong>
            <div className={`site-loading-track${preparing || progress === null ? ' is-indeterminate' : ''}`} role="progressbar" aria-label="场地模型加载进度" aria-valuemin={0} aria-valuemax={100} aria-valuenow={preparing || progress === null ? undefined : Math.round(progress)} aria-valuetext={preparing ? '正在准备场景' : progress === null ? '正在下载模型' : undefined}>
              <span style={preparing || progress === null ? undefined : { width: `${progress}%` }} />
            </div>
            <span>{preparing ? '正在准备场景' : progress === null ? '正在下载模型' : `${Math.round(progress)}%`}</span>
          </div>
        </div>
      )}
      {loadError && (
        <div className="site-error" role="alert">
          {site.poster && <img src={resolveAssetUrl(site.poster)} alt="" />}
          <strong>场地模型加载失败</strong>
          <span>{loadError}</span>
          <button
            type="button"
            onClick={() => {
              // 先清掉本应用的 Cache Storage（模型缓存 + 发布包 SW 的内容缓存）再重试：
              // 截断的模型字节一旦进了缓存，不清就一直命中它、点多少次都一样。
              void clearAssetCaches().finally(() => setRetryAttempt(value => value + 1));
            }}
          >
            重新加载
          </button>
        </div>
      )}
      {calibrating && ready && basemap && site.placement && (
        <SiteCalibrationPanel
          draft={draft}
          wireframe={wireframe}
          onWireframeChange={setWireframe}
          canWriteBack={canWriteBack}
          writeBackState={writeBack}
          onWriteBack={() => { void writeBackPlacement(); }}
        />
      )}
    </div>
  );
});
