import type { BasemapConfig } from '../../config/schema';
import { enuFromLngLat, latToMercator, lngLatFromEnu, lngToMercator, MAX_MERCATOR_LAT, mercatorToLat, mercatorToLng, type LngLat } from '../../shared/geo';
import { makeGroundTile, prepareGroundUrls, type GroundTile } from './groundTiles';

/**
 * 流式影像地面（`docs/project/ROAM-PLAN-A.md` §2 S4a）。
 *
 * 与 `groundTiles.tilesAroundAnchor` 的区别：那一版是**固定一层、锚点对称**的一小片（`/site` 的场景窗口），
 * 这一版是**跟着相机视口走**的——相机移到哪，就铺到哪，退出视野的瓦片会被释放。二者的取图口径
 * 必须完全一致（同一套 `{z}/{x}/{y}/{s}` 替换），所以都走 `groundTiles` 里那几个共用函数。
 *
 * 本文件是**纯函数**（不碰 three.js）：输入「地面窗口 + 每像素多少米」，输出「用哪一层、要哪些瓦片」。
 * 这样选层与裁剪逻辑可以单测，不必起 WebGL。
 */

/** 赤道周长（米）——与 `groundTiles.ts` 同一常量，用于「每像素米数 ↔ 层级」换算。 */
const EARTH_CIRCUMFERENCE_M = 40_075_016.686;

/** 一张瓦片按 256 逻辑像素设计。 */
const TILE_PX = 256;

/**
 * 一次最多铺多少张（含注记层）。`/map` 那套二维引擎的上限是 240，三维场景里每张瓦片是一个
 * `Mesh`（一次 draw call），64 张已经是「地面比模型还贵」的量级，所以取更紧的值；超了就降层。
 */
export const STREAM_TILE_CAP = 64;

/** 地面被相机看到的范围（米，相对锚点；东/北为正）。 */
export interface GroundWindow {
  west: number;
  east: number;
  south: number;
  north: number;
}

export interface GroundStreamView {
  window: GroundWindow;
  /** 当前相机下，屏幕 1 像素覆盖多少米（由窗口宽度 / 画布宽度得到）。 */
  metersPerPixel: number;
}

export interface GroundStreamPlan {
  /** 本帧选用的层级。 */
  zoom: number;
  /** 因为超出 `cap` 被迫降过层（画面上表现为地面更糊）。 */
  degraded: boolean;
  /** 按「中心优先」排好序的瓦片，直接按顺序挂载。 */
  tiles: GroundTile[];
}

/** 层级上限与下限：直接沿用配置（`/map` 二维引擎用的是同一组值）。 */
function zoomLimits(basemap: BasemapConfig): { min: number; max: number } {
  if (basemap.kind !== 'tiles') return { min: 1, max: 19 };
  return { min: basemap.minZoom, max: basemap.maxZoom };
}

/**
 * 「屏幕 1 像素多少米」→ 该用哪一层。
 * 取最接近的整数层：`tileMeters(z) / 256 ≈ 米/像素` ⇒ `z = log2(C·cos(lat) / (256 · 米/像素))`。
 * 层级越高瓦片越清、张数越多，所以调用方还要拿 `cap` 往下压（见 `planGroundStream`）。
 */
export function zoomForPixelScale(metersPerPixel: number, lat: number, minZoom: number, maxZoom: number): number {
  if (!Number.isFinite(metersPerPixel) || metersPerPixel <= 0) return maxZoom;
  const perTile = EARTH_CIRCUMFERENCE_M * Math.cos((lat * Math.PI) / 180);
  const raw = Math.log2(perTile / (TILE_PX * metersPerPixel));
  return Math.min(maxZoom, Math.max(minZoom, Math.round(raw)));
}

/** 某个窗口在某层需要哪些瓦片（含端点）。窗口按四个角换算，够用且不必处理投影非线性。 */
export function tileRangeForWindow(
  anchor: LngLat,
  zoom: number,
  window: GroundWindow,
): { minX: number; maxX: number; minY: number; maxY: number } {
  const count = 2 ** zoom;
  const corners: LngLat[] = [
    lngLatFromEnu(anchor, { east: window.west, north: window.south }),
    lngLatFromEnu(anchor, { east: window.east, north: window.south }),
    lngLatFromEnu(anchor, { east: window.west, north: window.north }),
    lngLatFromEnu(anchor, { east: window.east, north: window.north }),
  ];
  const xs: number[] = [];
  const ys: number[] = [];
  for (const corner of corners) {
    const lat = Math.max(-MAX_MERCATOR_LAT, Math.min(MAX_MERCATOR_LAT, corner.lat));
    xs.push(Math.floor(lngToMercator(corner.lng) * count));
    ys.push(Math.floor(latToMercator(lat) * count));
  }
  return {
    minX: Math.min(...xs),
    maxX: Math.max(...xs),
    minY: Math.min(...ys),
    maxY: Math.max(...ys),
  };
}

/** 窗口里的所有格子，**中心优先**排序（相机附近的先出图）。 */
function cellsForWindow(
  anchor: LngLat,
  zoom: number,
  window: GroundWindow,
): Array<{ x: number; y: number; distance: number }> {
  const { minX, maxX, minY, maxY } = tileRangeForWindow(anchor, zoom, window);
  const count = 2 ** zoom;
  const centerEast = (window.west + window.east) / 2;
  const centerNorth = (window.south + window.north) / 2;
  const cells: Array<{ x: number; y: number; distance: number }> = [];
  for (let x = minX; x <= maxX; x += 1) {
    const wrappedX = ((x % count) + count) % count;
    for (let y = minY; y <= maxY; y += 1) {
      if (y < 0 || y >= count) continue;
      // 格子中心（墨卡托中点）→ 经纬度 → 相对锚点的米，用它与窗口中心的距离排序。
      const lng = mercatorToLng((wrappedX + 0.5) / count);
      const lat = mercatorToLat((y + 0.5) / count);
      const { east, north } = enuFromLngLat(anchor, { lng, lat });
      cells.push({ x, y, distance: Math.hypot(east - centerEast, north - centerNorth) });
    }
  }
  cells.sort((a, b) => a.distance - b.distance || a.x - b.x || a.y - b.y);
  return cells;
}

/**
 * 本帧该铺哪些瓦片。
 *
 * 顺序：先用「每像素米数」算出理想层级，再拿 `cap` 一层一层往下压（压过就把 `degraded` 置真），
 * 到最小层还超量就按中心优先截断。**永远返回底图在前、注记层在后**，与固定铺地一致。
 */
export function planGroundStream(
  anchor: LngLat,
  view: GroundStreamView,
  basemap: BasemapConfig,
  cap: number = STREAM_TILE_CAP,
): GroundStreamPlan {
  const urls = prepareGroundUrls(basemap);
  const { min, max } = zoomLimits(basemap);
  if (!urls) return { zoom: max, degraded: false, tiles: [] };
  const layers = urls.overlay ? 2 : 1;
  const maxCells = Math.max(1, Math.floor(cap / layers));

  let zoom = zoomForPixelScale(view.metersPerPixel, anchor.lat, min, max);
  let degraded = false;
  let cells = cellsForWindow(anchor, zoom, view.window);
  while (cells.length > maxCells && zoom > min) {
    zoom -= 1;
    degraded = true;
    cells = cellsForWindow(anchor, zoom, view.window);
  }
  const kept = cells.slice(0, maxCells);
  if (kept.length < cells.length) degraded = true;

  const base = kept.map(cell => makeGroundTile(urls, zoom, cell.x, cell.y, cell.x, false));
  const notes = urls.overlay ? kept.map(cell => makeGroundTile(urls, zoom, cell.x, cell.y, cell.x, true)) : [];
  return { zoom, degraded, tiles: [...base, ...notes] };
}
