import * as THREE from 'three';
import type { BasemapConfig } from '../../config/schema';
import type { LngLat } from '../../shared/geo';
import { placeGroundTile, tileMeters, type GroundTile } from './groundTiles';
import { planGroundStream, STREAM_TILE_CAP, type GroundStreamView } from './groundStream';

/**
 * 流式影像地面的**场景侧**（`docs/project/ROAM-PLAN-A.md` §2 S4a）。
 *
 * `groundStream.ts` 负责「该铺哪些瓦片」（纯函数、可单测），这里负责「怎么铺、怎么收」：
 * 每帧拿计划做一次增删对账——视野内的挂上、离开视野的**真释放**（材质 + 贴图 + 网格），
 * 所以一路漫游下去显存与 draw call 都不会单调上涨。
 *
 * 与固定铺地（`GroundLayer.ts`）的两处刻意差异：
 * 1. **失败即摘掉**，而不是留一张黑面：流式场景里相机还会回来，摘掉之后下一帧会重试；
 * 2. 几何体按**层级**缓存（层内复用一份 `PlaneGeometry`），而不是整层共用一份。
 */

export interface GroundStreamerOptions {
  anchor: LngLat;
  basemap: BasemapConfig;
  overlayOpacity: number;
  /** 地面高度（场景米），一般是 `placement.elevationM - GROUND_DROP_M`。 */
  elevation: number;
  cap?: number;
  onUpdate?(): void;
}

export interface GroundStreamerStats {
  /** 当前挂着的瓦片数（含注记层）。 */
  live: number;
  /** 其中贴图已就位的张数。 */
  ready: number;
  /** 贴图失败（含备用源）并被摘掉的张数。 */
  failed: number;
  /** 本帧选用的层级。 */
  zoom: number;
  /** 本帧因超上限降过层。 */
  degraded: boolean;
  /** 累计挂上 / 累计释放——探针靠这两个数证明「离开视野的真的被放下了」。 */
  mounted: number;
  released: number;
}

export interface GroundStreamer {
  group: THREE.Group;
  readonly stats: GroundStreamerStats;
  /** 按当前相机视野对账一次。同一帧内重复调用是幂等的。 */
  update(view: GroundStreamView): void;
  setOpacity(value: number): void;
  setElevation(value: number): void;
  dispose(): void;
}

interface LiveTile {
  tile: GroundTile;
  mesh: THREE.Mesh;
  material: THREE.MeshBasicMaterial;
  ready: boolean;
}

export function createGroundStreamer(options: GroundStreamerOptions): GroundStreamer {
  const group = new THREE.Group();
  group.name = 'site-ground-stream';
  const cap = options.cap ?? STREAM_TILE_CAP;
  const stats: GroundStreamerStats = {
    live: 0,
    ready: 0,
    failed: 0,
    zoom: 0,
    degraded: false,
    mounted: 0,
    released: 0,
  };
  // 探针与 `?perf=1` 直接从场景树读，不必另开全局变量（沿用 S2 的做法）。
  group.userData.groundStats = stats;

  const loader = new THREE.TextureLoader();
  loader.setCrossOrigin('anonymous');
  const geometries = new Map<number, THREE.PlaneGeometry>();
  const live = new Map<string, LiveTile>();
  let disposed = false;

  const geometryFor = (zoom: number): THREE.PlaneGeometry => {
    const cached = geometries.get(zoom);
    if (cached) return cached;
    const size = tileMeters(zoom, options.anchor.lat);
    const geometry = new THREE.PlaneGeometry(size, size);
    geometry.rotateX(-Math.PI / 2);
    geometries.set(zoom, geometry);
    return geometry;
  };

  const release = (key: string): void => {
    const entry = live.get(key);
    if (!entry) return;
    live.delete(key);
    entry.material.map?.dispose();
    entry.material.dispose();
    entry.mesh.removeFromParent();
    stats.released += 1;
  };

  const mount = (tile: GroundTile): void => {
    const material = new THREE.MeshBasicMaterial({
      transparent: tile.overlay,
      opacity: tile.overlay ? options.overlayOpacity : 1,
      depthWrite: !tile.overlay,
      polygonOffset: true,
      polygonOffsetFactor: 1,
      polygonOffsetUnits: 1,
    });
    const mesh = new THREE.Mesh(geometryFor(tile.z), material);
    const placement = placeGroundTile(tile, options.anchor);
    mesh.position.set(placement.east, options.elevation, -placement.north);
    mesh.renderOrder = tile.overlay ? 1 : 0;
    mesh.userData.groundTile = tile.key;
    group.add(mesh);
    const entry: LiveTile = { tile, mesh, material, ready: false };
    live.set(tile.key, entry);
    stats.mounted += 1;

    const load = (url: string, fallbackUrl?: string) => {
      loader.load(
        url,
        texture => {
          // 期间被释放 / 整层销毁 ⇒ 这张贴图谁也不认，直接丢掉（否则每帧换视野都在漏显存）。
          if (disposed || live.get(tile.key) !== entry) {
            texture.dispose();
            return;
          }
          texture.colorSpace = THREE.SRGBColorSpace;
          material.map = texture;
          material.needsUpdate = true;
          entry.ready = true;
          options.onUpdate?.();
        },
        undefined,
        () => {
          if (disposed || live.get(tile.key) !== entry) return;
          if (fallbackUrl) {
            load(fallbackUrl);
            return;
          }
          // 主源与备用源都挂了：摘掉这张，下一帧若还在视野内会重新挂载（换层/回访都能自愈）。
          stats.failed += 1;
          release(tile.key);
          options.onUpdate?.();
        },
      );
    };
    load(tile.url, tile.fallbackUrl);
  };

  const recount = (): void => {
    let ready = 0;
    for (const entry of live.values()) if (entry.ready) ready += 1;
    stats.live = live.size;
    stats.ready = ready;
  };

  return {
    group,
    stats,
    update(view) {
      if (disposed) return;
      const plan = planGroundStream(options.anchor, view, options.basemap, cap);
      stats.zoom = plan.zoom;
      stats.degraded = plan.degraded;
      const wanted = new Set(plan.tiles.map(tile => tile.key));
      for (const key of [...live.keys()]) if (!wanted.has(key)) release(key);
      for (const tile of plan.tiles) if (!live.has(tile.key)) mount(tile);
      recount();
    },
    setOpacity(value) {
      const next = Math.min(1, Math.max(0, value));
      for (const entry of live.values()) {
        if (!entry.tile.overlay) continue;
        entry.material.opacity = next;
        entry.material.needsUpdate = true;
      }
    },
    setElevation(value) {
      for (const entry of live.values()) entry.mesh.position.y = value;
    },
    dispose() {
      disposed = true;
      for (const key of [...live.keys()]) release(key);
      for (const geometry of geometries.values()) geometry.dispose();
      geometries.clear();
      group.removeFromParent();
      group.clear();
      recount();
    },
  };
}
