/**
 * 三维院区标定面板的状态与固化（`docs/project/ROAM-PLAN-A.md` §2 S3）。
 *
 * 滑杆只改「草稿」：草稿经 `SiteScene` 的一个 ref 即时作用到**已加载**的模型根上
 * （改矩阵 + 重算热点锚点），不重建场景——32 MB 的模型不可能跟着滑杆重下。
 * 满意之后：
 * - 「应用」把草稿写进 `config/overrides.ts` 的本地覆盖层（刷新仍在、优先级高于 museum.json）；
 * - 「复制 JSON」给出一段可直接粘回 `config/museum.json` 的片段；
 * - 「复位」清掉覆盖层，回到配置文件里的值。
 *
 * 锚点（经纬度）不在这里改：站点是纯静态部署，锚点应该跟着 `/map` 的点位走，
 * 面板只把它读出来显示。
 */
import { useCallback, useMemo, useState } from 'react';
import { loadOverrides, saveOverrides } from '../../config/overrides';
import type { GroundConfig, PlacementConfig, SiteModelConfig } from '../../config/schema';

/** 配置里没写 `placement` / `ground` 时的兜底，与 `schema.ts` 的默认值一致。 */
export const DEFAULT_PLACEMENT: PlacementConfig = {
  anchor: { lng: 0, lat: 0 },
  headingDeg: 0,
  elevationM: 0,
  scale: 1,
};

export const DEFAULT_GROUND: GroundConfig = { zoom: 18, radius: 1, overlayOpacity: 1 };

export interface PlacementDraft {
  placement: PlacementConfig;
  ground: GroundConfig;
  /** 更新航向 / 高度 / 缩放（锚点不动）。 */
  set(patch: Partial<Omit<PlacementConfig, 'anchor'>>): void;
  /** 注记层影像的透明度。 */
  setOpacity(opacity: number): void;
  /** 草稿是否已经写进本地覆盖层。 */
  saved: boolean;
  /** 写进本地覆盖层（刷新仍在）。 */
  save(): void;
  /** 清掉覆盖层，回到 `config/museum.json` 的值。 */
  reset(): void;
  /** 可直接粘回 `config/museum.json` 的 JSON 片段。 */
  json: string;
}

const round = (value: number, digits: number) => Number(value.toFixed(digits));

/** 去掉浮点噪声：滑杆拖出来的 12.000000000000002 不该写进配置文件。 */
function tidy(placement: PlacementConfig): PlacementConfig {
  return {
    anchor: { lng: placement.anchor.lng, lat: placement.anchor.lat },
    headingDeg: round(placement.headingDeg, 2),
    elevationM: round(placement.elevationM, 3),
    scale: round(placement.scale, 4),
  };
}

/** 可直接粘回 `config/museum.json` 的片段（纯函数，便于单测）。 */
export function placementSnippet(placement: PlacementConfig, ground: GroundConfig): string {
  const clean = tidy(placement);
  return [
    '"placement": {',
    `  "anchor": { "lng": ${clean.anchor.lng}, "lat": ${clean.anchor.lat} },`,
    `  "headingDeg": ${clean.headingDeg},`,
    `  "elevationM": ${clean.elevationM},`,
    `  "scale": ${clean.scale}`,
    '},',
    `"ground": { "zoom": ${ground.zoom}, "radius": ${ground.radius}, "overlayOpacity": ${round(ground.overlayOpacity, 2)} }`,
  ].join('\n');
}

function storedSite(): { placement?: PlacementConfig; ground?: GroundConfig } | undefined {
  return loadOverrides().site;
}

export function usePlacementDraft(site: SiteModelConfig | undefined): PlacementDraft {
  // `site` 是 `loadConfig` 已经并过本机覆盖层的配置（`src/config/loadConfig.ts:14`），
  // 所以它天然就是「上次标定完的样子」，草稿从它起步。
  const initial = useMemo(
    () => ({ placement: site?.placement ?? DEFAULT_PLACEMENT, ground: site?.ground ?? DEFAULT_GROUND }),
    [site],
  );

  const [placement, setPlacement] = useState<PlacementConfig>(initial.placement);
  const [ground, setGround] = useState<GroundConfig>(initial.ground);

  const set = useCallback((patch: Partial<Omit<PlacementConfig, 'anchor'>>) => {
    setPlacement(current => ({ ...current, ...patch }));
    setSaved(false);
  }, []);

  const setOpacity = useCallback((overlayOpacity: number) => {
    setGround(current => ({ ...current, overlayOpacity }));
    setSaved(false);
  }, []);

  const json = useMemo(() => placementSnippet(placement, ground), [placement, ground]);

  // 挂载时如果本机已经有和草稿一致的覆盖，就直接显示「已应用」。
  const [saved, setSaved] = useState(() => {
    const stored = storedSite();
    if (!stored?.placement || !stored.ground) return false;
    return placementSnippet(stored.placement, stored.ground) === placementSnippet(initial.placement, initial.ground);
  });

  const save = useCallback(() => {
    const next = loadOverrides();
    saveOverrides({
      ...next,
      site: {
        placement: tidy(placement),
        ground: { ...ground, overlayOpacity: round(ground.overlayOpacity, 2) },
      },
    });
    setSaved(true);
  }, [placement, ground]);

  /**
   * 复位 = 清掉本机覆盖层 + 重新加载页面。
   *
   * 为什么必须重载：`loadConfig` 启动时就把覆盖层并进配置了（`src/config/loadConfig.ts:14`），
   * 内存里的 `site.placement` 已经是「被覆盖后」的值，光清存储改不回配置文件里的值。
   * 标定是开发期的一次性动作，重载一次比在内存里维护两份值可靠得多。
   */
  const reset = useCallback(() => {
    const next = loadOverrides();
    delete next.site;
    saveOverrides(next);
    setPlacement(initial.placement);
    setGround(initial.ground);
    setSaved(false);
    window.location.reload();
  }, [initial]);

  return { placement, ground, set, setOpacity, saved, save, reset, json };
}
